// Category A (overlay) — behavior borrowed from react-aria-components, look owned in src.
import {
  OverlayArrow,
  Tooltip as AriaTooltip,
  TooltipTrigger,
} from "react-aria-components";
import type {
  TooltipProps as AriaTooltipProps,
  TooltipTriggerComponentProps,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { resolveOffset } from "./resolveOffset";
import "./Tooltip.css";

export interface TooltipProps
  extends Omit<AriaTooltipProps, "className" | "children">,
    Pick<TooltipTriggerComponentProps, "delay" | "closeDelay"> {
  /** Whether to show the arrow. */
  showArrow?: boolean;
  /** Tooltip content. */
  content: ReactNode;
  /** Target element that opens the tooltip. */
  children: ReactNode;
  /** Additional class (optional). sd-tooltip is always preserved. */
  className?: string;
  /** Forwarded to the underlying tooltip DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function Tooltip({
  showArrow = true,
  content,
  children,
  delay,
  closeDelay,
  className,
  ref,
  // TooltipTrigger owns the open state. Passing it straight through to AriaTooltip makes RAC create
  // a **separate** local state (Tooltip.mjs: adopts localState when
  // `props.isOpen != null || props.defaultOpen != null`), leaving two owners: local state controls
  // rendering while the trigger's context state controls internal behavior — they diverge from
  // hover/focus. Pass it to the trigger the same way as Menu.
  isOpen,
  defaultOpen,
  onOpenChange,
  offset,
  ...props
}: TooltipProps) {
  return (
    <TooltipTrigger
      delay={delay}
      closeDelay={closeDelay}
      isOpen={isOpen}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
      <AriaTooltip
        {...props}
        ref={ref}
        // The stand-off from the trigger, read off `tooltip.offset` (see resolveOffset.ts). RAC's
        // own default is 0, which set the box flush against the trigger and the arrow over it.
        offset={offset ?? resolveOffset("--sd-tooltip-offset")}
        className={
          className ? `sd-tooltip sd-type-caption-medium ${className}` : "sd-tooltip sd-type-caption-medium"
        }
      >
        {showArrow && (
          <OverlayArrow className="sd-tooltip__arrow">
            <svg
              width="10"
              height="10"
              viewBox="0 0 10 10"
              aria-hidden="true"
              className="sd-tooltip__arrow-icon"
            >
              <path d="M0 0 L5 5 L10 0" />
            </svg>
          </OverlayArrow>
        )}
        {content}
      </AriaTooltip>
    </TooltipTrigger>
  );
}

/* Tooltip.css — .sd-tooltip
   규칙: sd- 프리픽스 / 평평한 단일 클래스 / 상태는 react-aria data-* / Cmp 토큰 참조. */
.sd-tooltip {
  max-width: var(--sd-tooltip-max-width);
  background: var(--sd-tooltip-background);
  color: var(--sd-tooltip-foreground);
  border: var(--sd-tooltip-border-width) solid var(--sd-tooltip-border);
  border-radius: var(--sd-tooltip-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-shadow: var(--sd-tooltip-shadow);
  padding: var(--sd-tooltip-padding-block) var(--sd-tooltip-padding-inline);
}

.sd-tooltip[data-entering] {
  animation: sd-tooltip-enter var(--sd-tooltip-animation-duration) var(--sd-easing-decelerate);
}

.sd-tooltip[data-exiting] {
  animation: sd-tooltip-exit var(--sd-tooltip-animation-duration) var(--sd-easing-accelerate);
}

.sd-tooltip__arrow {
  display: block;
  fill: var(--sd-tooltip-arrow-background);
  stroke: var(--sd-tooltip-arrow-border);
  stroke-width: var(--sd-tooltip-arrow-stroke-width);
  /* react-aria sets an inline transform (translate) here to position the arrow, which
     would override a rotate. So the placement rotation lives on the svg child via this
     inherited local var. Base points down; values point the arrow AT the trigger. */
  --sd-tooltip-arrow-rotate-current: 0deg;
}
.sd-tooltip__arrow[data-placement="bottom"] {
  --sd-tooltip-arrow-rotate-current: 180deg;
}
.sd-tooltip__arrow[data-placement="left"] {
  --sd-tooltip-arrow-rotate-current: -90deg;
}
.sd-tooltip__arrow[data-placement="right"] {
  --sd-tooltip-arrow-rotate-current: 90deg;
}
.sd-tooltip__arrow-icon {
  display: block;
  transform: rotate(var(--sd-tooltip-arrow-rotate-current, 0deg));
}

@keyframes sd-tooltip-enter {
  from {
    opacity: 0;
    transform: translateY(var(--sd-tooltip-translate-enter));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sd-tooltip-exit {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(var(--sd-tooltip-translate-exit));
  }
}

@media (prefers-reduced-motion: reduce) {
  .sd-tooltip[data-entering],
  .sd-tooltip[data-exiting] {
    animation: none;
  }
}
